import type { Constitution } from "@trellis/schema";

/** First line of every CODEOWNERS file Trellis writes; files without it are never overwritten. */
export const generatedHeader =
  "# Generated by trellis from .trellis/constitution.yaml. Edit the constitution, not this file.";

const pattern = (glob: string): string => {
  const rooted = glob.startsWith("/") || glob.startsWith("**") ? glob : `/${glob}`;
  return rooted.endsWith("/**") ? rooted.slice(0, -2) : rooted;
};

/**
 * CODEOWNERS for a constitution: the humans own everything, and every tier 3 and tier 2 path
 * names them explicitly so a later catch-all can never drop their review (ADR-0004).
 */
export const codeownersFor = (constitution: Constitution): string => {
  const owners = constitution.humans.join(" ");
  const protectedPaths = [...constitution.paths.tier3, ...constitution.paths.tier2];
  const lines = [
    generatedHeader,
    `* ${owners}`,
    ...protectedPaths.map((glob) => `${pattern(glob)} ${owners}`),
  ];
  return `${lines.join("\n")}\n`;
};
